-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('dressing-in-ways-that-feel-good', 'Dressing in Ways That Feel Good', 'For anyone who wants getting dressed to feel easier and kinder. Each day is one small way to choose clothes that feel comfortable, care for what you already own and enjoy how you show up in the world, whatever your shape or budget.', 'Self-Care', 365, array['Self-Care', 'Self-Esteem', 'Body']::text[], 1, '2026-11-06T17:00:00+00:00'::timestamptz),
  ('planning-a-calmer-week', 'Planning a Calmer Week', 'For anyone whose weeks feel crowded or rushed. Each day is one small way to look ahead, choose what matters most, leave room for rest and let the plan bend when life changes.', 'Focus', 365, array['Stress', 'Habits', 'Goals']::text[], 1, '2026-11-06T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('dressing-in-ways-that-feel-good', 'planning-a-calmer-week');

